import unittest

from solucao import total_do_pedido, troco_do_cliente


class TestFechandoOPedido(unittest.TestCase):
    def test_devolve_o_total_do_pedido(self):
        """a caixa devolve 37.5 quando o preco e 12.5 e a quantidade e 3"""
        self.assertEqual(total_do_pedido(12.5, 3), 37.5)

    def test_devolve_o_total_de_um_item(self):
        """a caixa devolve 8 quando o preco e 8 e a quantidade e 1"""
        self.assertEqual(total_do_pedido(8, 1), 8)

    def test_devolve_o_troco_do_cliente(self):
        """a caixa devolve 12.5 de troco quando o cliente paga 50"""
        self.assertEqual(troco_do_cliente(50, 12.5, 3), 12.5)

    def test_arredonda_o_troco_em_duas_casas(self):
        """a caixa devolve 6.7 de troco quando o preco e 1.1 e a quantidade e 3"""
        self.assertEqual(troco_do_cliente(10, 1.1, 3), 6.7)

    def test_devolve_zero_quando_o_pagamento_nao_cobre(self):
        """a caixa devolve 0 quando o pagamento nao cobre o pedido"""
        self.assertEqual(troco_do_cliente(3, 1.1, 3), 0)

