def total_do_pedido(preco, quantidade):
    """devolve o total do pedido"""
    assert quantidade > 0
    total = preco * quantidade
    return total


def troco_do_cliente(pago, preco, quantidade):
    """devolve o troco do cliente; quando o pagamento nao cobre, devolve 0"""
    total = total_do_pedido(preco, quantidade)
    if pago < total:
        return 0
    return round(pago - total, 2)
